  tools.exec_command({cmd:"cat AGENTS.md",max_output_tokens:6500}),
  tools.exec_command({cmd:"sed -n '1,420p' home/home.nix",max_output_tokens:11000}),
  tools.exec_command({cmd:"cat home/agent.nix",max_output_tokens:8000}),
  tools.exec_command({cmd:"cat flake.nix config/zellij/config.kdl config/windows-terminal.json config/starship.toml config/lazygit/config.yml",max_output_tokens:15000}),
  tools.exec_command({cmd:"rg -n --hidden --glob '!.git/**' --glob '!**/flake.lock' --glob '!AGENTS.md' --glob '!bespoke/**' 'micro|\\bEDITOR\\b|\\bVISUAL\\b|\\bhelix\\b|\\bhx\\b|core.editor|nswitch|home-manager' .",max_output_tokens:7000}),
  tools.exec_command({cmd:"ls -ld /etc/os-release /etc/NIXOS ~/.config/helix ~/.config/zellij/config.kdl ~/.config/home-manager ~/.nix-profile ~/.local/state/nix/profiles/home-manager",max_output_tokens:2000})
]);
